import json
data, _ = load_namespace("cases.py")
extra = data["EXTRA_CASES"]
assert len(extra) >= 2, "Add at least two cases."
ids = [case["id"] for case in extra]
assert len(set(ids)) == len(ids) and all(item.startswith("X") for item in ids)
signature = lambda case: json.dumps([case["now"], case["packets"]], sort_keys=True)
known = {signature(case) for case in data["PUBLIC_CASES"]}
for case in extra:
    assert signature(case) not in known, "Use distinct test inputs."
    known.add(signature(case))
    assert set(case["expected"]) == {"node-01", "node-02"}
    for value in case["expected"].values():
        assert set(value) == {"status", "temperature", "measured_at", "age"}
        assert value["status"] in ("NORMAL", "HIGH", "STALE", "MISSING")
